 static string FormatDownloadProgress(long bytes,long? total){string size=(bytes/1024.0).ToString("0.0")+" KB";return total.HasValue&&total.Value>0?"下载中 "+size+" / "+(total.Value/1024.0).ToString("0.0")+" KB · "+Math.Min(100,bytes*100.0/total.Value).ToString("0")+"%":"下载中 "+size+" · 正在接收";}
 void DownloadPlugin(string address,CatalogEntry entry,TextBlock status,ProgressBar progress,Button trigger){status.Visibility=Visibility.Visible;status.Text="正在连接下载服务器…";progress.Visibility=Visibility.Visible;progress.IsIndeterminate=true;trigger.IsEnabled=false;string temp=Path.Combine(Path.GetTempPath(),"conan-plugin-"+Guid.NewGuid().ToString("N")+".conanplugin");var elapsed=System.Diagnostics.Stopwatch.StartNew();long last=-1000;Task.Run(()=>{try{PluginManager.Download(address,temp,(bytes,total)=>{if(elapsed.ElapsedMilliseconds-last<100&&(!total.HasValue||bytes<total.Value))return;last=elapsed.ElapsedMilliseconds;if(!Dispatcher.HasShutdownStarted)Dispatcher.BeginInvoke(new Action(()=>{status.Text=FormatDownloadProgress(bytes,total);progress.IsIndeterminate=!total.HasValue||total.Value<=0;if(!progress.IsIndeterminate)progress.Value=Math.Min(100,bytes*100.0/total.Value);}));});if(entry!=null)PluginCatalog.VerifyDownloaded(entry,temp);if(Dispatcher.HasShutdownStarted){DeletePluginTemp(temp);return;}Dispatcher.BeginInvoke(new Action(()=>{try{status.Text=entry==null?"下载完成；请确认安装。":"下载完成，已校验；请确认安装。";progress.IsIndeterminate=false;progress.Value=100;if(IsVisible)ConfirmPlugin(temp);}catch(Exception error){status.Text="安装失败："+error.Message;}finally{DeletePluginTemp(temp);trigger.IsEnabled=true;}}));}catch(Exception error){DeletePluginTemp(temp);if(!Dispatcher.HasShutdownStarted)Dispatcher.BeginInvoke(new Action(()=>{status.Text="下载失败："+error.Message;progress.IsIndeterminate=false;trigger.IsEnabled=true;}));}});}
 static void DeletePluginTemp(string file){try{if(File.Exists(file))File.Delete(file);}catch(IOException){}catch(UnauthorizedAccessException){}}
 void ConfirmPlugin(string file){
  var manifest=PluginManager.Inspect(file);
  string message=manifest.Name+"  "+manifest.Version+"\n\n"+manifest.Description+"\n\n声明用途："+String.Join("、",manifest.Capabilities)+"\n\n代码插件以当前Windows账户权限运行。请只安装可信来源的包。安装后仍需手动启用。";
  if(MessageBox.Show(this,message,"安装独立插件包",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;
  assistant.Plugins.Install(file);ShowPage("插件中心");
 }
